mapper.update:
update notification
set
	notification_read = 'Y',
	notification_rtime = systimestamp
where notification_no = #{notificationNo}
	and notification_receiver = #{empNo}

mapper.delete:
delete from notification
where notification_no = #{notificationNo}
	and notification_receiver = #{empNo}

mapper.select:
select * from ( select rownum rn, TMP.* from ( select notification_no as notificationNo, notification_receiver as notificationReceiver, project_no as projectNo, notification_type as notificationType, notification_target as notificationTarget, notification_url as notificationUrl, notification_content as notificationContent, notification_read as notificationRead, notification_ctime as notificationCtime from notification where notification_receiver = #{empNo}
and notification_read = 'N'
order by notification_ctime desc ) TMP ) where rn between #{startRow} and #{endRow}

	select count(*) from notification
	where notification_receiver = #{empNo}

    	and notification_read = 'N'
